    ("P", "燃料油", "燃油锅炉"):    {"CO": 0.6, "NOx": 10.06, "SO2": 20, "VOC": 2.88, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
    ("P", "其它液体燃料", "燃油锅炉"): {"CO": 0.6, "NOx": 10.06, "SO2": 0, "VOC": 0.13, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
