    ("H", "转炉煤气", "燃气锅炉"):  {"CO": 1.3, "NOx": 1.35, "SO2": 0, "VOC": 0.05, "PM25": 0.03, "PM10": 0.03, "BC": 0, "OC": 0, "unit": "g/m3"},
