    ("H", "原油", "燃油锅炉"):      {"CO": 0.6, "NOx": 7.24, "SO2": 0, "VOC": 0.13, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
    ("H", "柴油", "燃油锅炉"):      {"CO": 0.6, "NOx": 7.4, "SO2": 3, "VOC": 0.13, "PM25": 0.5, "PM10": 0.5, "BC": 0.14, "OC": 0.01},
    ("H", "燃料油", "燃油锅炉"):    {"CO": 0.6, "NOx": 10.06, "SO2": 20, "VOC": 0.19, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.05},
    ("H", "其它液体燃料", "燃油锅炉"): {"CO": 0.6, "NOx": 10.06, "SO2": 0, "VOC": 0.13, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
    ("H", "石油焦", "燃油锅炉"):    {"CO": 0.6, "NOx": 10.06, "SO2": 0, "VOC": 33, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
    ("H", "其它石油制品", "燃油锅炉"): {"CO": 0.6, "NOx": 10.06, "SO2": 0, "VOC": 0.13, "PM25": 0.62, "PM10": 0.85, "BC": 0.04, "OC": 0.01},
}
NOX_CAP = [(100, 8.96), (300, 8.19), (float("inf"), 7.21)]  # MW threshold -> EF g/kg (note b of D.1)

C1 = {  # (sector, tech) -> (sr, ar)
    ("P", "煤粉炉"): (0.15, 0.25), ("P", "流化床炉"): (0.15, 0.44), ("P", "自动炉排层燃炉"): (0.15, 0.85),
    ("H", "煤粉炉"): (0.15, 0.25), ("H", "流化床炉"): (0.15, 0.44), ("H", "自动炉排层燃炉"): (0.15, 0.85),
}
C2 = {  # (sector, tech) -> (fPM2.5, fPM10)
    ("P", "煤粉炉"): (0.06, 0.23), ("P", "流化床炉"): (0.07, 0.29), ("P", "自动炉排层燃炉"): (0.10, 0.33),
    ("H", "煤粉炉"): (0.06, 0.23), ("H", "流化床炉"): (0.07, 0.29), ("H", "自动炉排层燃炉"): (0.10, 0.33),
}
C3 = {  # (sector, tech) -> (fBC, fOC)
    ("P", "煤粉炉"): (0.002, 0), ("P", "流化床炉"): (0.002, 0), ("P", "自动炉排层燃炉"): (0.002, 0),
    ("H", "煤粉炉"): (0.002, 0), ("H", "流化床炉"): (0.002, 0), ("H", "自动炉排层燃炉"): (0.002, 0),
}

COAL_FUELS = {"一般烟煤", "原煤", "无烟煤", "褐煤", "煤制品", "其他洗煤"}
GAS_FUELS = {"天然气", "焦炉煤气", "高炉煤气", "转炉煤气", "发生炉煤气", "其他煤气", "炼厂干气"}
LIQUID_FUELS = {"柴油", "原油", "燃料油", "石油焦", "其他石油制品", "汽油", "煤油"}
LNG_LPG = {"液化天然气", "液化石油气"}
NOEF_REASON = {
    "生物燃料": "EF_MISSING_BIOMASS",
    "城市生活垃圾（用于燃料）": "EF_MISSING_MSW",
    "工业废料（用于燃料）": "EF_MISSING_INDUSTRIAL_WASTE",
    "其他燃料": "EF_MISSING_OTHER_FUEL",
    "润滑油": "EF_MISSING_LUBE_OIL",
}


def fuel_map(label):
    label = (label or "").strip()
    if label in COAL_FUELS:
        return "煤炭", "coal"
    if label == "焦炭":
        return "焦炭", "coal"
    if label == "煤矸石（用于燃料）":
        return "煤矸石", "coal"
    if label in GAS_FUELS:
        return label, "gas"
    if label in LNG_LPG:
        return label, "lnglpg"
    if label in LIQUID_FUELS:
        return label, "liquid"
    if label == "其他焦化产品":
        return "其它焦化产品", "other_solid"
    return label, "noef"


TECH_MAP = {
    "煤粉炉": "煤粉炉",
    "循环流化床锅炉": "流化床炉",
    "流化床炉": "流化床炉",
    "链条炉": "自动炉排层燃炉",
    "层燃炉": "自动炉排层燃炉",
    "其他层燃炉": "自动炉排层燃炉",
    "抛煤机炉": "自动炉排层燃炉",
    "自动炉排层燃炉": "自动炉排层燃炉",
}

POLLUTANTS = ["SO2", "NOx", "CO", "VOC", "PM2.5", "PM10", "BC", "OC", "NH3"]

# ------------------------------------------------------------------ control facilities
fac_by_credit = defaultdict(lambda: defaultdict(lambda: defaultdict(list)))
for r in cf:
    cred = r[HC["统一社会信用代码"]].strip()
    if not cred:
        continue
    out = r[HC["对应的排放口代码"]].strip()
    fname = r[HC["废气治理设施名称"]].strip()
    proc = r[HC["处理工艺名称"]].strip()
    try:
        eff = float(r[HC["去除效率（%）"]])
    except Exception:
        continue
    if out == "DZGL":
        fac_by_credit[cred]["P"][fname].append((proc, eff))
    elif out == "GYGL":
        fac_by_credit[cred]["I"][fname].append((proc, eff))
    elif out == "QT":
        fac_by_credit[cred]["QT"][fname].append((proc, eff))

FAC_SO2, FAC_NOX, FAC_VOC, FAC_PM = "脱硫（酸）设施", "脱硝设施", "挥发性有机物治理设施", "除尘设施"


def control_eff(credit, kind, fac_type):
    """Return (mean_eff, processes) for the best-matched facilities (kind first, QT fallback)."""
    pool = fac_by_credit[credit]
    tags = [kind, "QT"] if kind in ("P", "I") else ["QT"]
    for tag in tags:
        items = pool.get(tag, {}).get(fac_type, [])
        if items:
            effs = [e for _, e in items]
            procs = sorted({p for p, _ in items})
            return sum(effs) / len(effs), ";".join(procs)
    return None, ""


# ------------------------------------------------------------------ helpers
def fnum(x):
    if x is None:
        return ""
    if isinstance(x, float) and abs(x) < 1e-12:
        return 0
    return round(x, 6)


def activity_amount(r, slot):
    if slot == 1:
        total = r[H["燃料一消耗量"]].strip()
        gen, heat = r[I_GEN1].strip(), r[I_HEAT1].strip()
    else:
        total = r[H["燃料二消耗量"]].strip()
        gen, heat = r[I_GEN2].strip(), r[I_HEAT2].strip()
    if gen or heat:
        return (float(gen) if gen else 0.0) + (float(heat) if heat else 0.0)
    if total:
        return float(total)
    return None


def sector_of(ind):
    return "P" if ind in {"4411", "4412", "4417"} else "H"


def nox_ef_capacity(cap_mw):
    for thr, ef in NOX_CAP:
        if cap_mw <= thr:
            return ef
    return 7.21


def component_ef(sector, fuel_label, tech_code, boiler_type):
    """Return (ef_row, tech_used, reason)."""
    if boiler_type == "燃气轮机":
        return None, None, "EF_MISSING_GAS_TURBINE"
    d1fuel, group = fuel_map(fuel_label)
    if group == "noef":
        return None, None, NOEF_REASON.get(d1fuel, "EF_MISSING_UNKNOWN")
    if group == "coal":
        tech = TECH_MAP.get(tech_code)
        if tech is None:
            return None, None, "EF_MISSING_COAL_TECH"
        key = (sector, d1fuel, tech)
        return (D1[key], tech, None) if key in D1 else (None, None, "EF_MISSING_COAL_TECH")
    if group in ("gas", "lnglpg"):
        key = (sector, d1fuel, "燃气锅炉")
        return (D1[key], "燃气锅炉", None) if key in D1 else (None, None, "EF_MISSING_GAS")
    if group == "liquid":
        key = (sector, d1fuel, "燃油锅炉")
        return (D1[key], "燃油锅炉", None) if key in D1 else (None, None, "EF_MISSING_LIQUID")
    if group == "other_solid":
        key = (sector, d1fuel, "不分技术")
        return (D1[key], "不分技术", None) if key in D1 else (None, None, "EF_MISSING_OTHER")
    return None, None, "EF_MISSING_UNKNOWN"


def material_params(sector, tech, row, slot):
    if slot == 1:
        s_raw = row[H["燃料一平均收到基含硫量"]].strip()
        aar_raw = row[H["燃料一平均收到基灰分（%）"]].strip()
    else:
        s_raw = row[H["燃料二平均收到基含硫量"]].strip()
        aar_raw = row[H["燃料二平均收到基灰分（%）"]].strip()
    if not s_raw or not aar_raw:
        return None
    S, Aar = float(s_raw), float(aar_raw)
    sr, ar = C1[(sector, tech)]
    f25, f10 = C2[(sector, tech)]
    fBC, fOC = C3[(sector, tech)]
    return {"S": S, "sr": sr, "Aar": Aar, "ar": ar, "f25": f25, "f10": f10, "fBC": fBC, "fOC": fOC}


def calc_component_pollutant(sector, tech, ef_row, mp, poll, cap_mw=None):
    """Return (ef_value, ef_unit, params_list) or (None, None, None)."""
    if poll == "NH3" or ef_row is None:
        return None, None, None
    unit = ("g/m3" if ef_row.get("unit") == "g/m3" else "g/kg")
    if poll == "SO2":
        if ef_row["SO2"] is MB:
            if mp is None:
                return None, None, None
            ef = 2 * mp["S"] * (1 - mp["sr"])  # formula (3)
            return ef, "g/kg", [("S", "input", mp["S"], "%"), ("SR", "table_C1", mp["sr"], "dimensionless")]
        return ef_row["SO2"], unit, []
    if poll == "NOx":
        v = ef_row["NOx"]
        if v == "CAP":
            if cap_mw is None:
                return None, None, None
            ef = nox_ef_capacity(cap_mw)
            return ef, "g/kg", [("CAPACITY", "input", cap_mw, "万千瓦")]
        return v, unit, []
    if poll == "CO":
        return ef_row["CO"], unit, []
    if poll == "VOC":
        return ef_row["VOC"], unit, []
    if poll in ("PM2.5", "PM10"):
        v = ef_row["PM25" if poll == "PM2.5" else "PM10"]
        if v is MB:
            if mp is None:
                return None, None, None
            f = mp["f25"] if poll == "PM2.5" else mp["f10"]
            ef = mp["Aar"] * (1 - mp["ar"]) * f  # formula (4)
            return ef, "g/kg", [("AAR", "input", mp["Aar"], "%"), ("AR", "table_C1", mp["ar"], "dimensionless"),
                                ("FPM", "table_C2", f, "dimensionless")]
        return v, unit, []
    if poll == "BC":
        v = ef_row["BC"]
        if v is MB:
            if mp is None:
                return None, None, None
            ef25 = mp["Aar"] * (1 - mp["ar"]) * mp["f25"]
            return ef25 * mp["fBC"], "g/kg", [("FBC", "table_C3", mp["fBC"], "dimensionless")]  # formula (5)
        return v, unit, []
    if poll == "OC":
        v = ef_row["OC"]
        if v is MB:
            if mp is None:
                return None, None, None
            ef25 = mp["Aar"] * (1 - mp["ar"]) * mp["f25"]
            return ef25 * mp["fOC"], "g/kg", [("FOC", "table_C3", mp["fOC"], "dimensionless")]  # formula (6)
        return v, unit, []
    return None, None, None


def standard_ref(poll, sector, comp_ef):
    if poll == "NH3":
        return "T/CSES 144-2024 §7.2 未提供电力热力源NH3产生系数"
    coal_any = any(ef is not None and ef["SO2"] is MB for _, ef, _, _, _ in comp_ef)
    base = "T/CSES 144-2024 §7.2.1.2 公式(2)"
    if coal_any:
        base += " 公式(3)-(6), 表D.1, 表C.1-表C.3"
    else:
        base += ", 表D.1"
    return base


# ------------------------------------------------------------------ classification
POWER_IND = {"4411", "4412", "4417", "4430"}
INDUSTRIAL_IND = set()
for r in b102:
    ind = r[H["行业类别代码"]].strip()
    if ind in POWER_IND:
        continue
    if ind.startswith(("1", "2", "3")) or ind in {"4511", "4512", "4520"}:
        INDUSTRIAL_IND.add(ind)


def classify(ind):
    if ind in POWER_IND:
        return "POWER", "CLASS_POWER_SECTOR"
    if ind in INDUSTRIAL_IND:
        return "INDUSTRIAL_BOILER", "CLASS_INDUSTRIAL_SECTOR"
    return "OUT_OF_SCOPE", "CLASS_OUT_OF_SCOPE"


# ------------------------------------------------------------------ build
decisions, dispositions, items = [], [], []
exceptions = defaultdict(lambda: {"sources": [], "pollutants": set()})

for k, r in enumerate(b102):
    sid = source_id_of_row[k]
    ind = r[H["行业类别代码"]].strip()
    decided, cls_rc = classify(ind)
    is_power_dev = bool(r[H["电站锅炉/燃气轮机编号"]].strip())
    kind = "P" if is_power_dev else "I"
    tech_code = (r[H["电站锅炉燃烧方式"]].strip() if is_power_dev else r[H["工业锅炉燃烧方式"]].strip())
    boiler_type = (r[H["电站锅炉/燃气轮机类型"]].strip() if is_power_dev else r[H["工业锅炉类型"]].strip())
    lnb = r[I_LNB_ZD if is_power_dev else I_LNB_GY].strip()
    cap_raw = r[H["对应机组装机容量（万千瓦）"]].strip()
    cap_mw = float(cap_raw) if cap_raw else None
    credit = r[H["统一社会信用代码"]].strip()

    disp = "included" if decided == "POWER" else ("not_target" if decided == "INDUSTRIAL_BOILER" else "out_of_scope")
    decisions.append([sid, "POWER", decided, disp, cls_rc])
    dispositions.append([sid, decided, disp, cls_rc])

    if decided != "POWER":
        continue

    sector = sector_of(ind)

    # ---- components (each fuel slot = one component)
    comps = []  # (component_id, fuel_label, amount, unit)
    if r[H["燃料一类型"]].strip():
        comps.append(["F1", r[H["燃料一类型"]].strip(), activity_amount(r, 1), r[H["燃料一消耗量单位"]].strip()])
    if r[H["燃料二类型"]].strip():
        comps.append(["F2", r[H["燃料二类型"]].strip(), activity_amount(r, 2), r[H["燃料二消耗量单位"]].strip()])
    ot = r[H["其他燃料消耗总量（吨标准煤）"]].strip()
    if ot and float(ot) > 0:
        dup = any(c[0] == "F1" and c[1] == "其他燃料" and c[2] is not None and abs(c[2] - float(ot)) < 1e-9 for c in comps)
        if not dup:
            comps.append(["F3", "其他燃料", float(ot), "吨标准煤"])

    comp_ef = []  # (cid, ef_row, tech, mp, reason)
    for cid, flabel, amt, unit in comps:
        ef_row, tech, reason = component_ef(sector, flabel, tech_code, boiler_type)
        mp = None
        if tech and ef_row:
            mp = material_params(sector, tech, r, 1 if cid == "F1" else 2)
        comp_ef.append((cid, ef_row, tech, mp, reason))

    # control efficiencies per pollutant (facility-reported; kind matched, QT fallback)
    ctl = {}
    for poll, ftype in [("SO2", FAC_SO2), ("NOx", FAC_NOX), ("VOC", FAC_VOC),
                        ("PM2.5", FAC_PM), ("PM10", FAC_PM), ("BC", FAC_PM), ("OC", FAC_PM)]:
        eff, procs = control_eff(credit, kind, ftype)
        ctl[poll] = (eff, procs)
    if ctl["NOx"][0] is None and lnb == "是":
        ctl["NOx"] = (22.0, "低氮燃烧技术")  # 附录A 表A.1

    for poll in POLLUTANTS:
        act_rec, par_rec, ctl_rec = [], [], []
        ok_all, gen_total, em_total = True, 0.0, 0.0
        fails = []
        for (cid, flabel, amt, unit), (ef_row, tech, mp, reason) in zip(comps, comp_ef):
            act_rec.append({"component_id": cid, "value": fnum(amt), "unit": unit if unit else ""})
            if poll == "PM10":
                fine_eff = (ctl["PM10"][0] if ctl["PM10"][0] is not None else 0.0)
                method = ctl["PM10"][1] if ctl["PM10"][0] is not None else "无适用治理"
                ctl_rec.append({"component_id": cid, "method": method, "efficiency": 0,
                                "fine_efficiency": round(fine_eff, 4), "coarse_efficiency": round(fine_eff, 4)})
            else:
                eff = (ctl[poll][0] if ctl[poll][0] is not None else 0.0)
                method = ctl[poll][1] if ctl[poll][0] is not None else "无适用治理"
                ctl_rec.append({"component_id": cid, "method": method, "efficiency": round(eff, 4),
                                "fine_efficiency": 0, "coarse_efficiency": 0})
            if amt is None:
                ok_all = False
                fails.append("ACTIVITY_MISSING")
                par_rec.append({"component_id": cid, "parameter_id": "", "mode": "", "value": "", "unit": ""})
                continue
            efv, efunit, params = calc_component_pollutant(sector, tech, ef_row, mp, poll, cap_mw)
            if efv is None:
                if poll == "NH3":
                    fails.append("NH3_EF_NOT_PROVIDED")
                elif reason:
                    fails.append(reason)
                else:
                    fails.append("EF_MISSING_%s" % poll)
                ok_all = False
                par_rec.append({"component_id": cid, "parameter_id": "EF", "mode": "table_D1",
                                "value": "", "unit": ""})
                continue
            params = params or []
            if efunit == "g/m3":
                if unit != "万立方米":
                    ok_all = False
                    fails.append("UNIT_MISMATCH_GAS")
                    par_rec.append({"component_id": cid})
                    continue
                gen = amt * efv / 100.0
            else:
                if unit not in ("吨", "吨标准煤"):
                    ok_all = False
                    fails.append("UNIT_MISMATCH")
                    par_rec.append({"component_id": cid})
                    continue
                gen = amt * efv / 1000.0
            gen_total += gen
            if poll == "PM10":
                fine_eff = (ctl["PM10"][0] if ctl["PM10"][0] is not None else 0.0) / 100.0
                coarse_eff = fine_eff
                ef25, u25, _ = calc_component_pollutant(sector, tech, ef_row, mp, "PM2.5", cap_mw)
                if ef25 is None:
                    ok_all = False
                    fails.append("PM_SPLIT_MISSING")
                    par_rec.append({"component_id": cid})
                    continue
                if efunit == "g/m3":
                    gen_fine = amt * ef25 / 100.0
                else:
                    gen_fine = amt * ef25 / 1000.0
                gen_coarse = gen - gen_fine
                em = gen_fine * (1 - fine_eff) + gen_coarse * (1 - coarse_eff)
            else:
                eff = (ctl[poll][0] if ctl[poll][0] is not None else 0.0) / 100.0
                em = gen * (1 - eff)
            em_total += em
            # parameter element: EF + extra params
            el = {"component_id": cid}
            if ef_row is not None and ef_row["NOx"] == "CAP" and poll == "NOx":
                el.update({"parameter_id": "EF_NOX", "mode": "table_D1_capacity", "value": efv, "unit": efunit})
            elif ef_row is not None and poll in ("SO2", "PM2.5", "PM10", "BC", "OC") and \
                    ef_row[poll if poll != "PM2.5" else "PM25"] is MB:
                el.update({"parameter_id": "EF_" + poll.replace(".", ""), "mode": "material_balance",
                           "value": efv, "unit": efunit})
            else:
                el.update({"parameter_id": "EF_" + poll.replace(".", ""), "mode": "table_D1",
                           "value": efv, "unit": efunit})
            par_rec.append(el)
            for pname, pmode, pval, punit in params:
                par_rec.append({"component_id": cid, "parameter_id": pname, "mode": pmode,
                                "value": pval, "unit": punit})

        status = "calculated" if ok_all else "information_insufficient"
        reason_code = "CALC_OK" if ok_all else ";".join(sorted(set(fails)))
        if not ok_all:
            for fc in sorted(set(fails)):
                exceptions[fc]["sources"].append(sid)
                exceptions[fc]["pollutants"].add(poll)

        items.append([sid, "POWER", poll, status, "产排污系数法(公式2)",
                      json.dumps(act_rec, ensure_ascii=False),
                      json.dumps(par_rec, ensure_ascii=False),
                      json.dumps(ctl_rec, ensure_ascii=False),
                      fnum(gen_total) if ok_all else "",
                      fnum(em_total) if ok_all else "",
                      standard_ref(poll, sector, comp_ef),
                      reason_code])

